head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "ULDMGT50101";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

scwin.form_listForm = { action: "", method: 'post', target: '' };

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'uldmgt50101.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name form_1_onsubmit
 * @description form_1 onsubmit 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.form_1_onsubmit = function(e){
    try {
        return false

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'uldmgt50101.form_1_onsubmit' }); }
};

/**
 * @method
 * @name img_66_onclick
 * @description img_66 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_66_onclick = async function(e){
    try {
        await scwin.reExtraction()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'uldmgt50101.img_66_onclick' }); }
};

/**
 * @method
 * @name img_80_onclick
 * @description img_80 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_80_onclick = async function(e){
    try {
        await scwin.formList()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'uldmgt50101.img_80_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_FormList
 * @description Form List 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_FormList = async function () {
    const sbmOptions = {
        id: "tx_fn_FormList",
        method: "post",
        action: "/filing/element.do",
        ref: "dma_FormListReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_ElementList_xhr
 * @description Element List xhr 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_ElementList_xhr = async function () {
    // ⛔주소가 없다 — as-is 는 «자기 자신» 에게 제출했는데(`self_submit`) 화면 자신의 액션 URL 을
    //   하나로 못 정했다(후보 0 또는 여럿). 빈 주소로 내보내면 «조용히 엉뚱한 곳» 이다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_ElementList_xhr"
    throw { bizMessage: "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_ElementList_xhr", unresolved: "action:self_submit:tx_fn_ElementList_xhr" };
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name elementList
 * @description element List 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.elementList = async function () {
    scwin.form_listForm.action = "/filing/byformElement.do";
    $c.util.getComponent('dma_FormListReq').set('method', "findByformElements");
    await scwin.tx_fn_ElementList_xhr();
};

/**
 * @method
 * @name onCompleteResponse
 * @description on Complete Response 처리
 * @param {*} responseText responseText
 * @returns {void}
 * @hidden N
 */
scwin.onCompleteResponse = function (responseText) {
    $c.util.getComponent('txt_formListDiv').setValue(responseText);
};

/**
 * @method
 * @name reExtraction
 * @description re Extraction 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.reExtraction = async function () {
    const formCd = $c.util.getComponent('dma_FormListReq').get('formCd');
    const formVer = $c.util.getComponent('dma_FormListReq').get('formVer');
    const _url = "/filing/extractElement.do?method=prepareReExtractElement&formCd=" + formCd + "&formVer=" + formVer;
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    await $c.win.openPopup((function (__u) { const __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(_url), { id: "reExtractPop", popupName: "reExtractPop" }, {});
};

/**
 * @method
 * @name formList
 * @description form List 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.formList = async function () {
    $c.util.getComponent('dma_FormListReq').set('method', "");
    await scwin.tx_fn_FormList();
};

/**
 * @method
 * @name historyBack
 * @description history Back 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.historyBack = async function () {
    await scwin.formList();
};
